CREATE TABLE ai_model_invocation(model_invocation_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),provider_code text NOT NULL CHECK(provider_code~'^[a-z][a-z0-9_-]*$'),model_name text NOT NULL CHECK(btrim(model_name)<>''),purpose_code text NOT NULL CHECK(purpose_code IN('source_text_review','source_visual_review','source_intro','referee_narration')),input_sha256 text NOT NULL CHECK(input_sha256~'^[0-9a-f]{64}$'),output_sha256 text CHECK(output_sha256~'^[0-9a-f]{64}$'),invocation_status text NOT NULL CHECK(invocation_status IN('pending','completed','failed')),prompt_tokens integer CHECK(prompt_tokens>=0),completion_tokens integer CHECK(completion_tokens>=0),started_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,error_code text,source_command_id bigint REFERENCES cmd_command(command_id),CHECK((invocation_status='pending' AND completed_at IS NULL) OR (invocation_status<>'pending' AND completed_at IS NOT NULL)));
